-- Site profile: name, titles, availability and CTA (single row per user)

create table "public"."profile" (
  "id" bigint primary key generated by default as identity,
  "image" text,
  "name" varchar,
  "primary_title" varchar,
  "secondary_title" varchar,
  "user" uuid,
  "is_active" boolean default true,
  "is_available" boolean,
  "at" varchar,
  "cta_link" text,
  constraint "profile_cta_link_key" unique ("cta_link")
);

alter table "public"."profile" add constraint "profile_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."profile" enable row level security;
create policy "Enable read access for all users" on "public"."profile" for select using (true);

grant all on "public"."profile" to postgres, anon, authenticated, service_role;
